mapper.select:
SELECT fs.id, fsd.id AS detailId, fs.code, fs.shop_id, fs.shop_name, fs.country_id, fs.country_name, fs.fulfillment_center, fs.delivery_status, (SELECT fd.code FROM first_mile_delivery fd WHERE fd.source_id = fs.id ORDER BY fd.create_time DESC LIMIT 1) AS deliveryCode, fs.platform_shipment_status, fs.shipment_create_time, fs.shipment_receive_time, fsd.platform_spu_no, fsd.platform_sku_no, fsd.fn_sku, fsd.sku_no, fsd.declare_qty, fsd.diff_qty, fsd.is_combination FROM fba_shipment fs INNER JOIN fba_shipment_detail fsd ON fs.id = fsd.main_id AND fsd.is_deleted = FALSE WHERE fs.is_deleted = FALSE
AND fs.code ILIKE concat('%',#{params.code}::text,'%')
AND fsd.sku_no in
#{item}
AND fs.shop_id in
#{shopId}
AND fs.country_id in
#{countryId}
AND fs.fulfillment_center ILIKE concat('%',#{params.fulfillmentCenter}::text,'%')
AND fs.delivery_status in
#{deliveryStatus}
AND fs.platform_shipment_status in
#{platformShipmentStatus}
AND fsd.platform_spu_no ILIKE concat('%',#{params.platformSpuNo}::text,'%')
AND fsd.fn_sku ILIKE concat('%',#{params.fnSku}::text,'%')
AND fsd.platform_sku_no ILIKE concat('%',#{params.platformSkuNo}::text,'%')
and fsd.is_combination = #{params.isCombination}
AND fsd.diff_qty ${params.diffRule} 0
AND fs.shipment_create_time >= #{params.shipmentCreateTimeList[0]} AND (#{params.shipmentCreateTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > fs.shipment_create_time
AND fs.shipment_receive_time >= #{params.shipmentReceiveTimeList[0]} AND (#{params.shipmentReceiveTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > fs.shipment_receive_time
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
fs.create_time DESC

SELECT fsd.id, fsd.main_id, fs.code, fs.fulfillment_center, fs.shop_id, fs.shop_name, fs.country_id, fs.country_name, fsd.platform_spu_no, fsd.platform_sku_no, fsd.fn_sku, fsd.sku_no, fsd.declare_qty, fsd.is_combination FROM fba_shipment_detail fsd INNER JOIN fba_shipment fs ON fs.id = fsd.main_id AND fsd.is_deleted = FALSE WHERE fs.is_deleted = FALSE
and fs.id in
#{id}

SELECT fs.id AS sourceId, fsd.id AS sourceDetailId, fs.code AS sourceCode, fs.shop_id AS channelId, fs.shop_name AS channelName, fsd.platform_spu_no, fsd.platform_sku_no, fsd.fn_sku, fsd.sku_id, fsd.sku_no, fsd.declare_qty FROM fba_shipment_detail fsd INNER JOIN fba_shipment fs ON fs.id = fsd.main_id AND fsd.is_deleted = FALSE WHERE fs.is_deleted = FALSE
and fs.id in
#{id}
